"use client";

import * as React from "react";
import { AlertCircle, ArrowRight, CircleSlash, RotateCcw } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TASK PROGRESS: work that takes minutes, not seconds
 *
 *   running    phases fill left to right; the current one sweeps;
 *              the status line names the phase as it morphs from
 *              one to the next; timer and stats roll; Cancel
 *   done       the last bar fills, a check draws itself, "Finished
 *              in 4m 12s"; Cancel grows into "Open report"
 *   error      the failed phase fills red, the reason opens in,
 *              "Stopped at reading"; the button becomes Retry
 *   cancelled  stopped by the user; the button folds away
 *
 * The button and the status line are one surface each: they
 * change shape and wording instead of being swapped. For deep
 * research, long builds and batch jobs. Tell people they can
 * leave; the card is what they come back to.
 * ───────────────────────────────────────────────────────── */

export type TaskProgressStatus = "running" | "done" | "error" | "cancelled";

export interface TaskStat {
  label: string;
  /** Numbers roll when they change. */
  value: React.ReactNode;
}

export interface TaskProgressProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  title: string;
  status: TaskProgressStatus;
  /** The stages, e.g. ["Searching", "Reading", "Writing"]. */
  phases: string[];
  /** Index of the current phase. */
  phase: number;
  /** Start time (ms); shows a live timer. */
  startedAt?: number;
  /** Total time (ms), if you know it once finished. */
  duration?: number;
  stats?: TaskStat[];
  /** A line under the progress, e.g. "You can close this tab. We'll keep going." */
  message?: string;
  onCancel?: () => void;
  onOpen?: () => void;
  openLabel?: string;
  errorText?: string;
  onRetry?: () => void;
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function formatTime(ms: number) {
  const s = Math.max(0, Math.floor(ms / 1000));
  return s < 60
    ? `${s}s`
    : `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, "0")}s`;
}

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** A block that opens to its height and folds back to nothing. */
function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      aria-hidden={!show || undefined}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{children}</div>
    </div>
  );
}

/** Seconds that roll up as they pass; minutes slide open at the first minute. */
function Elapsed({ ms, reduced }: { ms: number; reduced: boolean }) {
  const total = Math.max(0, Math.floor(ms / 1000));
  const minutes = Math.floor(total / 60);
  return (
    <span className="inline-flex items-baseline">
      <Reveal show={minutes > 0} reduced={reduced}>
        <NumberRoll value={minutes} suffix="m" duration={500} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={minutes ? total % 60 : total}
        format={minutes ? TWO_DIGITS : undefined}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 200ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function TaskProgress({
  title,
  status,
  phases,
  phase,
  startedAt,
  duration,
  stats,
  message,
  onCancel,
  onOpen,
  openLabel = "Open result",
  errorText,
  onRetry,
  className = "",
  ...props
}: TaskProgressProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [endedAt, setEndedAt] = React.useState<number | undefined>(undefined);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const actionRef = React.useRef<HTMLButtonElement>(null);

  const [seenStartedAt, setSeenStartedAt] = React.useState(startedAt);
  if (startedAt !== seenStartedAt) {
    setSeenStartedAt(startedAt);
    setNow(startedAt ?? 0);
  }

  if (running && endedAt !== undefined) setEndedAt(undefined);

  React.useEffect(() => {
    if (!running) {
      if (endedAt !== undefined) return;
      const frame = requestAnimationFrame(() => setEndedAt(Date.now()));
      return () => cancelAnimationFrame(frame);
    }
    if (startedAt === undefined) return;
    const initial = window.setTimeout(() => setNow(Date.now()), 0);
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      window.clearTimeout(initial);
      window.clearInterval(timer);
    };
  }, [running, startedAt, endedAt]);

  const elapsed =
    duration ??
    (startedAt === undefined
      ? undefined
      : (running ? now : (endedAt ?? now)) - startedAt);
  const current = Math.min(Math.max(phase, 0), phases.length - 1);

  // The one button: Cancel while it runs, Retry after a failure, the result once done.
  const action =
    running && onCancel
      ? { kind: "cancel", label: "Cancel", run: onCancel }
      : status === "error" && onRetry
        ? { kind: "retry", label: "Retry", run: onRetry }
        : status === "done" && onOpen
          ? { kind: "open", label: openLabel, run: onOpen }
          : null;
  const [lastAction, setLastAction] = React.useState(action);
  if (
    action &&
    (action.kind !== lastAction?.kind || action.label !== lastAction.label)
  )
    setLastAction(action);
  const shown = action ?? lastAction;
  const primary = action?.kind === "open";
  const hasAction = Boolean(action);

  // If the button folds away while focused (Cancel pressed), keep focus on the card instead of the page.
  React.useLayoutEffect(() => {
    if (!hasAction && document.activeElement === actionRef.current)
      cardRef.current?.focus({ preventScroll: true });
  }, [hasAction]);

  const statusLine = running
    ? phases[current]
    : status === "done"
      ? "Finished"
      : status === "error"
        ? `Stopped at ${phases[current].toLowerCase()}`
        : "Cancelled";
  const timeJoin = status === "done" ? "in" : "after";
  const showTime =
    (status === "done" || status === "cancelled") && elapsed !== undefined;
  const iconKey = status === "running" ? null : status;

  return (
    <div
      ref={cardRef}
      tabIndex={-1}
      className={`w-full rounded-xl border border-border bg-background p-4 outline-none ${className}`}
      {...props}
    >
      <div className="flex items-baseline justify-between gap-4">
        <p className="min-w-0 truncate text-[13.5px] font-medium text-foreground">
          {title}
        </p>
        {elapsed !== undefined && (
          <span
            aria-hidden="true"
            className="shrink-0 font-mono text-[11.5px] tabular-nums text-muted-foreground"
          >
            <Elapsed ms={elapsed} reduced={reduced} />
          </span>
        )}
      </div>

      {/* Each phase fills from the left when it's finished; the live one sweeps. */}
      <div className="mt-3.5 flex gap-1" aria-hidden="true">
        {phases.map((p, i) => {
          const complete = status === "done" || i < current;
          const failed = status === "error" && i === current;
          const live = running && i === current;
          return (
            <span
              key={p}
              className="relative h-1 flex-1 overflow-hidden rounded-full bg-border"
            >
              <span
                className={`absolute inset-0 origin-left rounded-full transition-colors duration-300 ${failed ? "bg-red-500" : "bg-foreground"}`}
                style={{
                  transform: complete || failed ? "none" : "scaleX(0)",
                  transition: reduced
                    ? "none"
                    : `transform 620ms ${MORPH}, background-color 300ms`,
                }}
              />
              <span
                className={`absolute inset-y-0 left-0 w-2/5 rounded-full bg-foreground/60 motion-reduce:hidden ${live ? "animate-[ui-scan_1.6s_cubic-bezier(0.45,0,0.55,1)_infinite]" : ""}`}
                style={{
                  opacity: live ? 1 : 0,
                  transition: reduced ? "none" : "opacity 300ms",
                }}
              />
            </span>
          );
        })}
      </div>

      <div aria-hidden="true" className="mt-2 flex gap-1 text-[11.5px]">
        {phases.map((p, i) => (
          <span
            key={p}
            className={`flex-1 truncate transition-colors duration-300 ${status === "error" && i === current ? "text-red-500" : running && i === current ? "text-foreground" : "text-muted-foreground"}`}
          >
            {p}
          </span>
        ))}
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {status === "done"
          ? `${title} finished${elapsed !== undefined ? ` in ${formatTime(elapsed)}` : ""}`
          : status === "error"
            ? `${title} failed. ${errorText ?? ""}`
            : status === "cancelled"
              ? `${title} cancelled`
              : `${phases[current]}`}
      </p>

      {stats && stats.length > 0 && (
        <p className="mt-3 flex flex-wrap gap-x-3 gap-y-1 text-[12px] text-muted-foreground">
          {stats.map((s) => (
            <span
              key={s.label}
              className="inline-flex items-baseline gap-[0.3em]"
            >
              <span className="font-mono tabular-nums text-foreground">
                {typeof s.value === "number" ? (
                  <NumberRoll value={s.value} duration={700} />
                ) : (
                  s.value
                )}
              </span>
              {s.label}
            </span>
          ))}
        </p>
      )}

      {message && (
        <Fold show={running} reduced={reduced}>
          <p className="pt-2 text-[12px] text-muted-foreground">{message}</p>
        </Fold>
      )}
      <Fold show={status === "error"} reduced={reduced}>
        <p className="pt-3 text-[12.5px] text-red-500">
          {errorText ?? "Something went wrong partway through."}
        </p>
      </Fold>

      <div className="mt-4 flex min-h-8 items-center justify-between gap-3">
        {/* One status line: it names the phase while it runs and becomes the outcome. */}
        <span
          aria-hidden="true"
          className="flex min-w-0 items-center text-[12px] text-muted-foreground"
        >
          <span
            className="relative flex h-3.5 shrink-0 items-center justify-center"
            style={{
              width: iconKey ? 14 : 0,
              marginRight: iconKey ? 6 : 0,
              transition: reduced
                ? "none"
                : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
            }}
          >
            <span
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              style={swap(iconKey === "done", reduced)}
            >
              <DrawnCheck drawn={iconKey === "done"} reduced={reduced} />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center text-red-500"
              style={swap(iconKey === "error", reduced)}
            >
              <AlertCircle className="size-3.5" />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center"
              style={swap(iconKey === "cancelled", reduced)}
            >
              <CircleSlash className="size-3.5" />
            </span>
          </span>
          <span className={`truncate ${running ? SHEEN : ""}`}>
            <TextMorph>{statusLine}</TextMorph>
          </span>
          {elapsed !== undefined && (
            <Reveal show={showTime} reduced={reduced}>
              <span className="inline-flex items-baseline pl-[0.3em] tabular-nums">
                <TextMorph>{timeJoin}</TextMorph>
                &nbsp;
                <Elapsed ms={elapsed} reduced={reduced} />
              </span>
            </Reveal>
          )}
        </span>

        {shown && (
          <Reveal show={Boolean(action)} reduced={reduced} className="shrink-0">
            <span className="block p-0.5">
              <button
                ref={actionRef}
                type="button"
                inert={!action}
                onClick={() => action?.run()}
                className={`cursor-pointer inline-flex h-8 items-center rounded-lg px-3 text-[12.5px] font-medium transition-[background-color,color,box-shadow,transform] duration-300 active:scale-[0.97] ${FOCUS} ${
                  primary
                    ? "bg-primary text-primary-foreground hover:bg-primary/90"
                    : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                }`}
              >
                <span
                  aria-hidden="true"
                  className="relative flex h-3 shrink-0 items-center justify-center overflow-hidden"
                  style={{
                    width: shown.kind === "retry" ? 12 : 0,
                    marginRight: shown.kind === "retry" ? 6 : 0,
                    transition: reduced
                      ? "none"
                      : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
                  }}
                >
                  <RotateCcw
                    className="size-3 shrink-0"
                    style={swap(shown.kind === "retry", reduced)}
                  />
                </span>
                <TextMorph>{shown.label}</TextMorph>
                <span
                  aria-hidden="true"
                  className="relative flex h-3.5 shrink-0 items-center justify-center overflow-hidden"
                  style={{
                    width: shown.kind === "open" ? 14 : 0,
                    marginLeft: shown.kind === "open" ? 6 : 0,
                    transition: reduced
                      ? "none"
                      : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
                  }}
                >
                  <ArrowRight
                    className="size-3.5 shrink-0"
                    style={swap(shown.kind === "open", reduced)}
                  />
                </span>
              </button>
            </span>
          </Reveal>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

